"use client"

import {
  FileText,
  Folder,
  LayoutGrid,
  Link as LinkIcon,
  LogOut,
  MessageCircle,
  Settings,
  TrendingUp,
  Users,
} from "lucide-react"
import type { ComponentType, ReactNode } from "react"

import { Sheet, SheetClose, SheetContent, SheetTrigger } from "@/components/ui/sheet"

interface NavItem {
  icon: ComponentType<{ className?: string }>
  label: string
}

interface NavSection {
  label: string
  items: NavItem[]
}

const SECTIONS: NavSection[] = [
  {
    label: "Workspace",
    items: [
      { icon: LayoutGrid, label: "Overview" },
      { icon: TrendingUp, label: "Analytics" },
      { icon: Folder, label: "Projects" },
    ],
  },
  {
    label: "Team",
    items: [
      { icon: Users, label: "Members" },
      { icon: Settings, label: "Settings" },
    ],
  },
  {
    label: "Resources",
    items: [
      { icon: FileText, label: "Billing" },
      { icon: LinkIcon, label: "API keys" },
      { icon: MessageCircle, label: "Help and support" },
    ],
  },
]

/**
 * `side="left"` and a fixed `300px` detent turn the Sheet into a navigation
 * drawer instead of a right-anchored panel. The handle's arrow-key axis
 * flips to ArrowLeft/ArrowRight automatically for horizontal sides.
 */
function NavDrawer({ trigger, onSignOut }: { trigger: ReactNode; onSignOut?: () => void }) {
  return (
    <Sheet side="left" detents={["300px"]}>
      <SheetTrigger asChild>{trigger}</SheetTrigger>
      <SheetContent aria-label="Navigation" className="flex flex-col p-0">
        <nav className="flex-1 overflow-y-auto p-3">
          {SECTIONS.map((section) => (
            <div key={section.label} className="mb-4">
              <div className="text-muted-foreground px-2 pb-1 text-xs font-medium">
                {section.label}
              </div>
              {section.items.map((item) => (
                <button
                  type="button"
                  key={item.label}
                  className="hover:bg-accent flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-sm"
                >
                  <item.icon className="h-4 w-4" />
                  {item.label}
                </button>
              ))}
            </div>
          ))}
        </nav>
        <div className="border-t p-3">
          <SheetClose
            className="hover:bg-accent static flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-sm no-underline hover:no-underline"
            data-scrollsheet-no-drag
            onClick={onSignOut}
          >
            <LogOut className="h-4 w-4" />
            Sign out
          </SheetClose>
        </div>
      </SheetContent>
    </Sheet>
  )
}

export { NavDrawer }
